// src/app/utils/google-maps-ready.util.ts
function waitForGoogleMaps() {
  return new Promise((resolve) => {
    const check = () => {
      if (window.google?.maps?.importLibrary) {
        window.google.maps.importLibrary("places").then(() => resolve());
      } else {
        setTimeout(check, 100);
      }
    };
    check();
  });
}

